import{_ as a,a as e,c as t}from"./chunks/framework.BkXmWmgX.js";const b=JSON.parse('{"title":"Tanstack-Query 더 잘 쓰기 | OTW for FE","titleTemplate":false,"description":"","frontmatter":{"layout":"post","title":"OTW for FE","titleTemplate":false,"lang":"ko"},"headers":[],"params":{"id":"7a30f366-9a28-4044-9643-c6c7f14270d8","title":"Tanstack-Query 더 잘 쓰기","date":"2024-04-17","coverUrl":null,"html":"<h2 data-notion-block-id=\\"23c8bcce-cdaa-47c1-80c9-74eb978f9c1e\\" id=\\"23c8bcce-cdaa-47c1-80c9-74eb978f9c1e\\">Tanstack-Query 더 잘 쓰기</h2><a href=\\"https://tanstack.com/query/v5/docs/framework/react/guides/render-optimizations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/query/v5/docs/framework/react/guides/render-optimizations</a><a href=\\"https://www.teemutaskula.com/blog/exploring-query-suspense\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.teemutaskula.com/blog/exploring-query-suspense</a><p data-notion-block-id=\\"532a89ae-f97c-44b7-97cc-225e7d9c0cbf\\"><b>심윤섭</b>: 서버 상태 관리를 Tanstack query에 위임하는 것으로 쉽게 효율적으로 렌더링 최적화를 이뤘지만 이미 너무 많은 상태를 관리하고 있어 더 최적화가 필요한 사람들이나, 사소하지만 불편한 UX를 제공하는 것을 막고자 하는 사람들에게 조언하는 글입니다. 둘 다 hook에 넣는 속성을 어떻게 잘 넣을 것인지를 생각해보게 하는 글이기 때문에 Tanstack-query를 쓰는 사람은 무조건 보시길 바랍니다.</p><p data-notion-block-id=\\"7a4bc0b0-9470-477a-a13c-61207fd3d426\\"><b>김대관</b>: 위의 최적화 기법 5개에서 React-Query가 비동기 처리에 강력한 도구인지를 알게 해줍니다. 특히나, <code>select</code> 와 메모이제이션을 혼합해서 쓰는 예제는 useEffect와 같은 선택적 렌더링에 활용할 수 있지 않을까 합니다. 비동기 관련 기능에서 강력한 도구이며 어느 부분이 좋은 지 글을 통해 더 이해하면 좋을 것 같습니다.</p><h2 data-notion-block-id=\\"83a9e1d2-a2db-4fa2-9f23-deefb811a4ba\\" id=\\"83a9e1d2-a2db-4fa2-9f23-deefb811a4ba\\">자바스크립트 객체 딥 다이브</h2><a href=\\"https://blog.frontend-almanac.com/js-object-structure\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.frontend-almanac.com/js-object-structure</a><p data-notion-block-id=\\"142d3847-9683-401a-b28a-055e59e65461\\"><b>심윤섭</b>: 객체의 내부 구조를 앎과 동시에 히든 클래스에 집중하여 내부에서 어떻게 동작하는지를 알려주고 있습니다. 이와 관련된 <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#b0fa8093-7010-49bd-9e12-b95e81fcacef\\">저번 글</a>을 보면 어떻게 실제 프로젝트에서 어떻게 적용할지를 생각해볼 수 있습니다.</p><h2 data-notion-block-id=\\"ecfe89ce-2cee-43c7-be3c-f18300662445\\" id=\\"ecfe89ce-2cee-43c7-be3c-f18300662445\\">당신은 GraphQL이 필요하지 않습니다.</h2><a href=\\"https://mxstbr.com/thoughts/graphql/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mxstbr.com/thoughts/graphql/</a><p data-notion-block-id=\\"5bc98715-758c-4cc2-992c-50f0b59f539a\\"><b>심윤섭</b>: GraphQL은 모든 사람을 위한 기술이 아니고, 특정 사람만을 위한 기술임을 강조하고 있습니다(사실 거의 모든 기술이 그렇죠). 항상 자신에게 맞는 <a href=\\"https://fe-developers.kakaoent.com/2023/230112-appropriate-technology/\\">적정 기술을 선택</a>하려고 해야 합니다.</p><h2 data-notion-block-id=\\"4327264d-2f0c-4fd5-8fcb-294cd30f95f3\\" id=\\"4327264d-2f0c-4fd5-8fcb-294cd30f95f3\\">Cloudflare의 출시 주간</h2><a href=\\"https://blog.cloudflare.com/blazing-fast-development-with-full-stack-frameworks-and-cloudflare\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/blazing-fast-development-with-full-stack-frameworks-and-cloudflare</a><a href=\\"https://blog.cloudflare.com/javascript-native-rpc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/javascript-native-rpc</a><p data-notion-block-id=\\"ce274998-25c3-4a67-90d5-7f60cceba929\\">주로 쓰이는 프레임워크(Next.js, Nuxt, ….)에서 D1, R2등 Cloudflare의 개발자 플랫폼에 쉽게 접근할 수 있도록 만들고, 관계형 데이터베이스인 D1을 Prisma를 통해 사용할 수 있다는 것을 보여주었습니다. 그리고 RPC 호출을 통해 다른 Worker에게 객체를 전달할 수 있는 등 여러 기능을 출시했습니다.</p><h2 data-notion-block-id=\\"c71f3f8f-e2c1-4742-ac34-0df1bec77e92\\" id=\\"c71f3f8f-e2c1-4742-ac34-0df1bec77e92\\">HTML 스트리밍으로 클라이언트 코드 줄이기</h2><a href=\\"https://aralroca.com/blog/html-streaming-over-the-wire\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aralroca.com/blog/html-streaming-over-the-wire</a><p data-notion-block-id=\\"a2e42c2a-963e-4036-87a5-92e728e4a9fa\\">Htmx에 영감을 얻어 클라이언트에서의 로직을 줄여서 웹 성능을 하고자 하는 라이브러리를 소개하는 글입니다.</p><h2 data-notion-block-id=\\"61aaa1c8-09c6-4d9f-8693-1f36c71f62c9\\" id=\\"61aaa1c8-09c6-4d9f-8693-1f36c71f62c9\\">Flow는 React 시장을 차지할 수 있을까</h2><a href=\\"https://medium.com/flow-type/announcing-component-syntax-b6c5285660d0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/flow-type/announcing-component-syntax-b6c5285660d0</a><p data-notion-block-id=\\"dc12b4a1-e110-4cc9-a75c-23d075ca889d\\">Flow 언어에서 React에서 타입 검사를 더 잘할 수 있도록 <code>component</code> / <code>hook</code> / <code>render</code> 유형을 만들었습니다.</p><p data-notion-block-id=\\"a20c69c5-3657-46e0-8fa5-3739e0164009\\"></p>"},"relativePath":"news/post/7a30f366-9a28-4044-9643-c6c7f14270d8.md","filePath":"news/post/[id].md"}'),c={name:"news/post/7a30f366-9a28-4044-9643-c6c7f14270d8.md"};function o(r,n,l,d,f,s){return e(),t("div")}const p=a(c,[["render",o]]);export{b as __pageData,p as default};
